exports.tf-aws:
# Generated by IP Plan-O-Matic. Review before applying.
# Tip: set Platform to AWS VPC on the Plan tab so host counts and minimum sizes match.

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/22"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "main"
  }
}

resource "aws_subnet" "servers" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.0.0/24"
  # availability_zone = "us-east-1a"
  tags = {
    Name = "Servers"
  }
}

resource "aws_subnet" "wifi_guest" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  # availability_zone = "us-east-1a"
  tags = {
    Name = "Wifi \"guest\""
  }
}

resource "aws_subnet" "vlan20" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  # availability_zone = "us-east-1a"
  tags = {
    Name = "10.0.2.0/24"
  }
}

exports.tf-azure:
# Generated by IP Plan-O-Matic. Review before applying.
# Tip: set Platform to Azure VNet on the Plan tab so host counts and minimum sizes match.

variable "resource_group_name" {
  type = string
}

variable "location" {
  type = string
}

resource "azurerm_virtual_network" "main" {
  name                = "vnet-main"
  address_space       = ["10.0.0.0/22"]
  location            = var.location
  resource_group_name = var.resource_group_name
}

resource "azurerm_subnet" "servers" {
  name                 = "snet-servers"
  resource_group_name  = var.resource_group_name
  virtual_network_name = azurerm_virtual_network.main.name
  address_prefixes     = ["10.0.0.0/24"]
}

resource "azurerm_subnet" "wifi_guest" {
  name                 = "snet-wifi-guest"
  resource_group_name  = var.resource_group_name
  virtual_network_name = azurerm_virtual_network.main.name
  address_prefixes     = ["10.0.1.0/24"]
}

resource "azurerm_subnet" "vlan20" {
  name                 = "snet-vlan20"
  resource_group_name  = var.resource_group_name
  virtual_network_name = azurerm_virtual_network.main.name
  address_prefixes     = ["10.0.2.0/24"]
}

exports.tf-gcp:
# Generated by IP Plan-O-Matic. Review before applying.
# Tip: set Platform to Google Cloud VPC on the Plan tab so host counts and minimum sizes match.

variable "region" {
  type = string
}

resource "google_compute_network" "main" {
  name                    = "vpc-main"
  auto_create_subnetworks = false
}

resource "google_compute_subnetwork" "servers" {
  name          = "servers"
  ip_cidr_range = "10.0.0.0/24"
  region        = var.region
  network       = google_compute_network.main.id
  description   = "Servers"
}

resource "google_compute_subnetwork" "wifi_guest" {
  name          = "wifi-guest"
  ip_cidr_range = "10.0.1.0/24"
  region        = var.region
  network       = google_compute_network.main.id
  description   = "Wifi \"guest\""
}

resource "google_compute_subnetwork" "vlan20" {
  name          = "vlan20"
  ip_cidr_range = "10.0.2.0/24"
  region        = var.region
  network       = google_compute_network.main.id
}
